CREATE TABLE public.crm_customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_lead_id uuid UNIQUE REFERENCES public.leads(id) ON DELETE SET NULL, name text NOT NULL, phone text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', billing_address text NOT NULL DEFAULT '', customer_type text NOT NULL DEFAULT 'residential', notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.crm_customers TO authenticated; GRANT ALL ON public.crm_customers TO service_role;
ALTER TABLE public.crm_customers ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner customers" ON public.crm_customers FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.crm_properties (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES public.crm_customers(id), label text NOT NULL DEFAULT 'Primary property', address text NOT NULL, notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(customer_id,address));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.crm_properties TO authenticated; GRANT ALL ON public.crm_properties TO service_role;
ALTER TABLE public.crm_properties ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner properties" ON public.crm_properties FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.crm_activity (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid REFERENCES public.leads(id) ON DELETE SET NULL, kind text NOT NULL, body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.crm_activity TO authenticated; GRANT ALL ON public.crm_activity TO service_role;
ALTER TABLE public.crm_activity ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner reads activity" ON public.crm_activity FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY "Owner records activity" ON public.crm_activity FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin'));
ALTER TABLE public.leads ADD COLUMN customer_id uuid REFERENCES public.crm_customers(id), ADD COLUMN pipeline_stage text NOT NULL DEFAULT 'new';
INSERT INTO public.crm_customers(id,source_lead_id,name,phone,email,created_at) SELECT id,id,name,coalesce(phone,''),coalesce(email,''),created_at FROM public.leads;
UPDATE public.leads SET customer_id=id,pipeline_stage=CASE status WHEN 'won' THEN 'approved' WHEN 'lost' THEN 'lost' ELSE status::text END;
INSERT INTO public.crm_properties(customer_id,address) SELECT customer_id,address FROM public.leads WHERE address IS NOT NULL AND length(trim(address))>0;
CREATE OR REPLACE FUNCTION public.sync_lead_customer() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; BEGIN cid:=coalesce(NEW.customer_id,NEW.id); INSERT INTO public.crm_customers(id,source_lead_id,name,phone,email) VALUES(cid,NEW.id,NEW.name,coalesce(NEW.phone,''),coalesce(NEW.email,'')) ON CONFLICT(id) DO UPDATE SET name=excluded.name,phone=excluded.phone,email=excluded.email; IF NEW.customer_id IS NULL THEN UPDATE public.leads SET customer_id=cid WHERE id=NEW.id; END IF; IF NEW.address IS NOT NULL AND length(trim(NEW.address))>0 THEN INSERT INTO public.crm_properties(customer_id,address) VALUES(cid,NEW.address) ON CONFLICT(customer_id,address) DO NOTHING; END IF; RETURN NEW; END; $$;
CREATE TRIGGER crm_sync_lead_customer AFTER INSERT OR UPDATE OF name,phone,email,address ON public.leads FOR EACH ROW EXECUTE FUNCTION public.sync_lead_customer();
CREATE OR REPLACE FUNCTION public.log_crm_lead_activity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN INSERT INTO public.crm_activity(lead_id,kind,body) VALUES(NEW.id,'lead','New lead received: '||NEW.name); ELSIF NEW.pipeline_stage IS DISTINCT FROM OLD.pipeline_stage THEN INSERT INTO public.crm_activity(lead_id,kind,body) VALUES(NEW.id,'stage','Sales stage manually recorded: '||NEW.pipeline_stage); END IF; RETURN NEW; END; $$;
CREATE TRIGGER crm_lead_activity AFTER INSERT OR UPDATE OF pipeline_stage ON public.leads FOR EACH ROW EXECUTE FUNCTION public.log_crm_lead_activity();
ALTER TABLE public.roof_jobs ADD COLUMN property_id uuid REFERENCES public.crm_properties(id);
ALTER TABLE public.roof_estimates ADD COLUMN property_id uuid REFERENCES public.crm_properties(id);
ALTER TABLE public.proposals ADD COLUMN property_id uuid REFERENCES public.crm_properties(id);
ALTER TABLE public.crm_invoices ADD COLUMN property_id uuid REFERENCES public.crm_properties(id);